import React, { useState } from 'react';
import { useStripe, useElements, PaymentElement } from '@stripe/react-stripe-js';

function CheckoutForm({ total, onSuccess }) {
  const stripe = useStripe();
  const elements = useElements();
  const [errorMessage, setErrorMessage] = useState(null);
  const [isProcessing, setIsProcessing] = useState(false);

  const handleSubmit = async (event) => {
    event.preventDefault();

    if (!stripe || !elements) return;

    setIsProcessing(true);

    const { error, paymentIntent } = await stripe.confirmPayment({
      elements,
      redirect: 'if_required', // Prevents automatic page redirect
    });

    if (error) {
      setErrorMessage(error.message);
      setIsProcessing(false);
    } else if (paymentIntent && paymentIntent.status === 'succeeded') {
      setIsProcessing(false);
      onSuccess(); // Triggers the success screen in Cart.js
    }
  };

  return (
    <form onSubmit={handleSubmit} className="bg-white p-6 rounded-lg shadow-md border border-gray-100">
      <PaymentElement className="mb-6" />
      
      {errorMessage && (
        <div className="text-red-600 text-sm mb-4 bg-red-50 p-3 rounded">
          {errorMessage}
        </div>
      )}
      
      <button 
        disabled={!stripe || isProcessing} 
        className={`w-full py-3 rounded-lg font-bold text-white transition ${isProcessing ? 'bg-blue-400' : 'bg-green-600 hover:bg-green-700'}`}
      >
        {isProcessing ? "Processing..." : `Pay $${total.toFixed(2)}`}
      </button>
    </form>
  );
}

export default CheckoutForm;
